function getUser(id: string | number) {
  if (typeof id === 'number') {
    // return from cache synchronously
    return { id, name: 'Cached User' }
  }
  // perform network fetch asynchronously
  return fetch('/users/' + id).then(r => r.json())
}

// Version A: single function adapts based on options
function applyDiscount(order: Order, options?: { percent?: number, amount?: number }) {
  if (options && options.percent != null) {
    order.total = order.total * (1 - options.percent)
    return order
  }
  if (options && options.amount != null) {
    order.total = order.total - options.amount
    return order
  }
  order.total = order.total - 10
  return order
}

// Version B: explicit functions with clear intent
function applyPercentageDiscount(order: Order, percent: number) {
  return { ...order, total: order.total * (1 - percent) }
}
function applyFixedDiscount(order: Order, amount: number) {
  return { ...order, total: order.total - amount }
}
